<?php
ini_set('display_errors', 1);
error_reporting(E_ALL);
require_once __DIR__ . '/../config.php';
header('Content-Type: text/plain; charset=utf-8');

try {
    $uploadDir = __DIR__ . '/../assets/uploads/hosts/';
    if (!is_dir($uploadDir)) {
        mkdir($uploadDir, 0755, true);
    }
    file_put_contents($uploadDir . 'WellingtonPeres.webp', base64_decode(''));
    file_put_contents($uploadDir . 'WellingtonPeres_thumb.webp', base64_decode(''));
    file_put_contents($uploadDir . 'WellingtonFilho.webp', base64_decode(''));
    file_put_contents($uploadDir . 'WellingtonFilho_thumb.webp', base64_decode(''));
    echo "Arquivos salvos com sucesso em assets/uploads/hosts/!
";

    $conn = connectDB();
    
    // Atualizar Wellington Peres (ID 22 - Ativo)
    $stmt1 = $conn->prepare("UPDATE hosts SET profile_picture = 'WellingtonPeres.webp' WHERE id = 22");
    $stmt1->execute();
    echo "Host ID 22 atualizado para WellingtonPeres.webp
";

    // Atualizar Wellington Filho (ID 5 - Inativo)
    $stmt2 = $conn->prepare("UPDATE hosts SET profile_picture = 'WellingtonFilho.webp' WHERE id = 5");
    $stmt2->execute();
    echo "Host ID 5 atualizado para WellingtonFilho.webp
";

    $check = $conn->query("SELECT id, full_name, profile_picture, status FROM hosts WHERE id IN (5, 22)")->fetchAll(PDO::FETCH_ASSOC);
    print_r($check);

} catch (Throwable $e) {
    echo "Erro: " . $e->getMessage() . "
";
}
